namespace {thread_local bool watching=false;thread_local size_t allocations=0,frees=0;int checks=0;}
void* operator new(std::size_t n){if(watching)++allocations;if(auto* p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void* operator new[](std::size_t n){return ::operator new(n);}
void operator delete(void* p)noexcept{if(watching&&p)++frees;std::free(p);}void operator delete[](void* p)noexcept{::operator delete(p);}
void operator delete(void* p,std::size_t)noexcept{::operator delete(p);}void operator delete[](void* p,std::size_t)noexcept{::operator delete(p);}
void check(bool ok,const char* message){++checks;if(!ok){std::cerr<<"FAIL "<<message<<'\n';std::exit(1);}}
void set(DrumProcessor& p,const juce::String& id,float value){auto* parameter=p.parameters.getParameter(id);parameter->setValueNotifyingHost(parameter->convertTo0to1(value));}
void idle(DrumProcessor& p){check(p.waitIdle(30000),"worker completes");}
juce::MemoryBlock state(DrumProcessor& p){juce::MemoryBlock b;p.getStateInformation(b);return b;}
void sampleFile(const juce::File& file,bool aiff=false,int channels=2,int frameCount=4410){auto stream=file.createOutputStream();check(stream!=nullptr,"fixture output");stream->setPosition(0);stream->truncate();std::unique_ptr<juce::AudioFormatWriter> writer;
    if(aiff)writer.reset(juce::AiffAudioFormat().createWriterFor(stream.release(),44100,static_cast<unsigned>(channels),24,{},0));else writer.reset(juce::WavAudioFormat().createWriterFor(stream.release(),44100,static_cast<unsigned>(channels),24,{},0));check(writer!=nullptr,"fixture writer");juce::AudioBuffer<float> audio(channels,frameCount);
    for(int c=0;c<channels;++c)for(int i=0;i<audio.getNumSamples();++i)audio.setSample(c,i,.4f*std::sin(static_cast<float>(i)*.027f)*(c==0?1.0f:.5f));check(writer->writeFromAudioSampleBuffer(audio,0,audio.getNumSamples()),"fixture PCM");}
